package com.cybershield.config;
import com.cybershield.security.JwtFilter; import com.cybershield.model.User; import com.cybershield.repository.UserRepository; import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService uds(UserRepository r){return email->{User u=r.findByEmail(email).orElseThrow(()->new UsernameNotFoundException(email));return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).disabled(!u.isActive()).build();};} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{h.csrf(c->c.disable()).cors(c->{}).headers(x->x.frameOptions(y->y.deny()).contentTypeOptions(z->{}).httpStrictTransportSecurity(t->t.includeSubDomains(true).maxAgeInSeconds(31536000))).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class);return h.build();} @Bean CorsConfigurationSource cors(@Value("${app.cors.allowed-origins:http://localhost:5173,http://127.0.0.1:5173}") String origins){List<String> allowed=new ArrayList<>(Arrays.stream(origins.split(",")).map(String::trim).filter(x->!x.isEmpty()).map(x->x.replaceAll("/+$", "")).toList());String productionOrigin="https://cybershield-production-358d.up.railway.app";if(!allowed.contains(productionOrigin))allowed.add(productionOrigin);CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(allowed);c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","PATCH","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(false);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
